def transform(grid, br, bc):
    """Apply transformation based on block position"""
    # Corners (both even): Transpose
    if br % 2 == 0 and bc % 2 == 0:
        return list(zip(*grid))

    # Center: Original
    if br == 1 and bc == 1:
        return grid

    # Top/bottom middle (row 0 or 2, col 1): Rot90
    if bc == 1 and br % 2 == 0:
        return list(zip(*grid[::-1]))

    # Left/right middle (col 0 or 2, row 1): Rot270
    if br == 1 and bc % 2 == 0:
        return list(zip(*grid))[::-1]

    return grid

