import json

def make_output(input_grid):
    """Generate 9x9 output from 3x3 input"""
    def transpose(g):
        return [list(r) for r in zip(*g)]

    def rot90(g):
        return [list(r) for r in zip(*g[::-1])]

    def rot270(g):
        return [list(r) for r in zip(*g)][::-1]

    even_br_blocks = [transpose(input_grid), rot90(input_grid), transpose(input_grid)]
    odd_br_blocks = [rot270(input_grid), input_grid, rot270(input_grid)]

    output = []
    for out_row in range(9):
        br = out_row // 3
        tr = out_row % 3

        row = []
        for col_idx in range(3):
            if br % 2 == 0:
                transform_list = even_br_blocks
            else:
                transform_list = odd_br_blocks

            block = transform_list[col_idx]
            row.extend(block[tr])

        output.append(row)

    return output

